# References are generated by tools/export_all_priors_reference.py from the
# current Python notebook, with its actual independent null draws.

test_that("the bundled null sample reproduces the notebook draws", {
  null <- ev_null_sample()
  expect_length(null, 100000L)
  expect_true(all(is.finite(null)))
  expect_equal(head(null, 5L), c(49.61297690645055, 9.423664797088913,
    -5.850566194162971, -0.36620651237260304, -1.537296283600286),
    tolerance = 1e-14)
  expect_identical(ev_null_sample(257L), head(null, 257L))
})

test_that("all five full-line prior densities match the Python definitions", {
  ref <- utils::read.csv(test_path("fixtures", "all_priors_densities.csv"))
  error <- vapply(seq_len(nrow(ref)), function(i) {
    row <- ref[i, ]
    p <- ev_prior(row$family, location = row$location, scale = row$scale)
    ev_prior_density(row$theta, p, log = TRUE) - row$log_density
  }, numeric(1))
  expect_true(all(is.finite(error)))
  expect_lt(max(abs(error)), 2e-9)
  spike <- ev_prior("horseshoe", location = -2, scale = 1.3)
  expect_identical(ev_prior_density(-2, spike, log = TRUE), Inf)
  expect_equal(ev_prior_density(0.7, ev_prior("rouder"), log = TRUE),
    stats::dcauchy(0.7, scale = 1 / sqrt(2), log = TRUE), tolerance = 1e-14)
})

test_that("all five full-line evidence mixtures match the Python notebook", {
  ref <- utils::read.csv(test_path("fixtures", "all_priors_evidence.csv"))
  error <- vapply(seq_len(nrow(ref)), function(i) {
    row <- ref[i, ]
    p <- ev_prior(row$family, location = row$location, scale = row$scale)
    ev_log_mixture(extension_data(row$n, row$t), p) - row$log_evidence
  }, numeric(1))
  expect_true(all(is.finite(error)))
  expect_lt(max(abs(error)), 2e-7)
})

test_that("new one-sided families recombine to their full-line mixtures", {
  x <- extension_data(8, 1.2)
  for (family in c("student_t5", "laplace", "horseshoe")) {
    full <- ev_prior(family, location = -2.3, scale = 0.7)
    pos <- ev_prior(family, location = -2.3, scale = 0.7,
                    alternative = "greater")
    neg <- ev_prior(family, location = -2.3, scale = 0.7,
                    alternative = "less")
    recombined <- .ev_logadd(full$log_positive_mass + ev_log_mixture(x, pos),
                            full$log_negative_mass + ev_log_mixture(x, neg))
    expect_lt(abs(recombined - ev_log_mixture(x, full)), 2e-7)
    reflected <- ev_prior(family, location = 2.3, scale = 0.7,
                          alternative = "greater")
    expect_lt(abs(ev_log_mixture(x, neg) - ev_log_mixture(-x, reflected)), 2e-7)
    expect_lt(abs(ev_log_mixture(1e60 * x, full) - ev_log_mixture(x, full)), 2e-7)
  }
})

test_that("MC bounds contain direct finite-sample means for every prior", {
  ref <- utils::read.csv(test_path("fixtures", "all_priors_mc_direct.csv"))
  null <- ev_null_sample(257L)
  for (family in unique(ref$family)) {
    rows <- ref[ref$family == family, ]
    p <- ev_prior(family, location = rows$location[1L], scale = rows$scale[1L])
    cal <- ev_calibration(p, method = "monte_carlo", null_t = null,
                          tolerance = 2e-7)
    got <- ev_pvalues(rows$log_c, cal)
    expect_true(all(got$mc_lower <= rows$empirical_mean + 5e-9))
    expect_true(all(got$mc_upper >= rows$empirical_mean - 5e-9))
    expect_true(all(got$mc_upper - got$mc_lower <= 2.01e-7))
    expect_equal(got$mc_estimate, (got$mc_lower + got$mc_upper) / 2,
                 tolerance = 1e-12)
    expect_equal(got$p_eville, pmin(got$mc_upper, rows$ville_bound),
                 tolerance = 1e-12)
    expect_lt(max(abs(got$mcse - rows$direct_mcse)), 2e-6)
  }
})

test_that("paper-sized MC calibration agrees on the same 100000 null draws", {
  ref <- utils::read.csv(test_path("fixtures", "all_priors_mc_100000.csv"))
  null <- ev_null_sample()
  for (family in unique(ref$family)) {
    rows <- ref[ref$family == family, ]
    p <- ev_prior(family, location = rows$location[1L], scale = rows$scale[1L])
    cal <- ev_calibration(p, method = "monte_carlo", null_t = null,
                          tolerance = rows$tolerance[1L])
    got <- ev_pvalues(rows$log_c, cal)
    expect_true(all(got$mc_lower <= rows$upper + 2e-8))
    expect_true(all(got$mc_upper >= rows$lower - 2e-8))
    expect_lt(max(abs(got$p_eville - rows$used)), 2.1e-5)
    expect_lt(max(abs(got$mcse - rows$mcse)), 2e-6)
    expect_true(all(got$p_eville <= rows$ville_bound + 1e-14))
  }
})
